// =============================================================================
// SW-015 Repository Certification (§255)
//
// Faithful port of the canonical reference implementation
//   crie-canonical-v1.0.2/workflows/shared/repository_certification.js
// covering §55/§428/§512/§527 certification, §511 quality score, §518 lifecycle
// states and §519 versioning. Weights, thresholds and the seven checks are
// TRANSCRIBED, not re-derived: no certification condition is invented here.
//
// ONE DELIBERATE DEVIATION FROM THE REFERENCE — the category enum.
// The reference declares a 16-value CATEGORY_ENUM labelled "§438 (R-05)" that is
// in fact the SUPERSEDED §415/§504 taxonomy (Capability, BusinessRule, DataModel,
// … Other). docs/SRD_CHANGES_SINCE_SPEC.md section D records that list as
// superseded and the §438 enum below as canonical; migration 0018's CHECK, the
// 0017 seed of configuration.knowledge_categories, PR-001 v1.2 and the canonical
// package's OWN migration 0018 all carry the §438 list, and all 962 knowledge
// units in the repository use it. Porting the reference's constant verbatim would
// make validCategory FALSE for every unit and nothing could ever be certified.
// ci/validate_taxonomy.py guards this file against that regression.
//
// This sub-workflow COMPUTES certification decisions and writes nothing. §512 is a
// pre-insertion gate (docs/architecture/Repository.md), so the per-unit decision
// must be available BEFORE the repository write persists lifecycle_state; the
// document-level result needs transactionCommitted and is therefore only computed
// once the caller supplies it. Retro-certifying already-persisted units is NOT a
// canonical operation and is not implemented.
// =============================================================================

// §438 canonical 16-value category enum (R-05). MUST match, character for
// character: repository.knowledge_units CHECK chk_knowledge_units_category
// (migration 0018), configuration.knowledge_categories (0017), and PR-001.
// NOTE the SPACES in 'Business Rule' and 'Known Issue'. There is no 'Other'.
const CATEGORY_ENUM = Object.freeze([
  'Feature', 'Business Rule', 'Requirement', 'Limitation', 'Configuration',
  'Permission', 'Calculation', 'Workflow', 'Notification', 'Integration',
  'Reporting', 'Security', 'API', 'Architecture', 'Known Issue', 'Recommendation',
]);

// §518 Knowledge Unit lifecycle states (migration 0018 CHECK).
const LIFECYCLE = Object.freeze({
  DRAFT: 'Draft', VALIDATED: 'Validated', CERTIFIED: 'Certified',
  DEPRECATED: 'Deprecated', ARCHIVED: 'Archived',
});

// §511 default quality weights and §512 default threshold, transcribed from the
// canonical reference. Overridable via config.repository (Principle 7).
const DEFAULT_WEIGHTS = Object.freeze({
  ocrConfidence: 0.25, citationCompleteness: 0.2, structuralQuality: 0.15,
  statementClarity: 0.15, categoryConfidence: 0.15, duplicateProbability: 0.1,
});
const DEFAULT_THRESHOLD = 0.6;

const clamp = (x) => Math.max(0, Math.min(1, x));

// --- §511 Knowledge Quality Score (0.00 -> 1.00), deterministic ---------------
function computeQualityScore(ku, ctx, config) {
  const w = (config.repository && config.repository.qualityWeights) || DEFAULT_WEIGHTS;

  const ocrConfidence = clamp(ctx.ocrConfidence == null ? 1 : ctx.ocrConfidence);
  const citationCompleteness = ctx.citationCount > 0 ? 1 : 0;
  const structuralQuality = (ku.sourcePage != null && ku.sourceParagraph != null) ? 1 : 0.5;
  const len = String(ku.statement || '').trim().length;
  const statementClarity = clamp(len === 0 ? 0 : len < 12 ? 0.4 : len > 400 ? 0.6 : 1);
  const categoryConfidence = CATEGORY_ENUM.includes(ku.category) ? 1 : 0;
  const duplicateProbability = clamp(ctx.duplicateProbability == null ? 0 : ctx.duplicateProbability);

  const score =
    w.ocrConfidence * ocrConfidence +
    w.citationCompleteness * citationCompleteness +
    w.structuralQuality * structuralQuality +
    w.statementClarity * statementClarity +
    w.categoryConfidence * categoryConfidence +
    w.duplicateProbability * (1 - duplicateProbability);

  const total = Object.values(w).reduce((a, b) => a + b, 0);
  return Math.round((score / total) * 100) / 100;
}

// --- §512 Per-Knowledge-Unit certification checklist --------------------------
// A unit failing ANY check stays Draft and is flagged reviewRequired (§513); it
// never enters retrieval. Certification is never partial.
function certifyKnowledgeUnit(ku, ctx, config) {
  const threshold = (config.repository && config.repository.qualityThreshold != null)
    ? config.repository.qualityThreshold : DEFAULT_THRESHOLD;
  const quality = computeQualityScore(ku, ctx, config);
  const checks = {
    atomicStatement: !!(ku.statement && String(ku.statement).trim()),
    validCategory: CATEGORY_ENUM.includes(ku.category),          // R-05
    authorityAssigned: !!ku.authoritySource,                     // §439
    evidenceExists: ctx.evidenceCount > 0,
    citationExists: ctx.citationCount > 0,                       // R-06
    duplicateCheckPassed: !ctx.isDuplicate,
    qualityAboveThreshold: quality >= threshold,
  };
  const certified = Object.values(checks).every(Boolean);
  return {
    knowledgeUnitId: ku.id,
    certified,
    qualityScore: quality,
    lifecycleState: certified ? LIFECYCLE.CERTIFIED : LIFECYCLE.DRAFT,
    checks,
    reviewRequired: !certified,   // §513 uncertain knowledge is not auto-certified
  };
}

// --- §428 / §527 Document-level Repository Certification ---------------------
function certifyDocument(args) {
  const unitResults = args.unitResults || [];
  const counts = args.counts || {};
  const certifiedUnits = unitResults.filter((r) => r.certified);
  const checks = {
    repositoryStructure: counts.document === 1,
    knowledgeQuality: certifiedUnits.length > 0,
    evidenceQuality: counts.evidence > 0,
    citationCompleteness: counts.citations > 0,
    embeddingAvailability: counts.embeddings > 0,
    versionIntegrity: !!args.repositoryVersion,
    transactionSuccess: args.transactionCommitted === true,
  };
  const certified = Object.values(checks).every(Boolean);
  const qualityScore = certifiedUnits.length
    ? Math.round((certifiedUnits.reduce((a, r) => a + r.qualityScore, 0) / certifiedUnits.length) * 100) / 100
    : 0;
  return {
    repositoryVersion: args.repositoryVersion || '',
    certified,
    certificationDate: new Date().toISOString(),
    qualityScore,
    checks,
    certifiedUnits: certifiedUnits.length,
    totalUnits: unitResults.length,
  };
}

// ===== SW-015 entry ==========================================================
const inp = $('When Called by WF-001').first().json;
const config = inp.config || {};
const units = inp.units || inp.accepted || inp.acceptedUnits || [];
if (!Array.isArray(units)) {
  throw new Error('SW-015: `units` must be an array of knowledge units to certify.');
}

// Per-unit context is DERIVED from the same bundle the repository writer receives,
// so certification cannot disagree with what is about to be persisted.
const evidence = inp.evidence || [];
const citations = inp.citations || [];
const evidenceByKu = new Map();
for (const e of evidence) {
  if (!evidenceByKu.has(e.knowledgeUnitId)) evidenceByKu.set(e.knowledgeUnitId, []);
  evidenceByKu.get(e.knowledgeUnitId).push(e);
}
const citationsByEvidence = new Set(citations.map((c) => c.evidenceId));
const duplicateKuIds = new Set(inp.duplicateKuIds || []);

const unitResults = units.map((ku) => {
  const kuEvidence = evidenceByKu.get(ku.id) || [];
  const ctx = {
    evidenceCount: kuEvidence.length,
    citationCount: kuEvidence.filter((e) => citationsByEvidence.has(e.id)).length,
    isDuplicate: duplicateKuIds.has(ku.id),
    // Absent inputs fall back to the canonical reference's own defaults
    // (ocrConfidence ?? 1, duplicateProbability ?? 0) — not to invented values.
    ocrConfidence: inp.ocrConfidence,
    duplicateProbability: ku.duplicateProbability,
  };
  return certifyKnowledgeUnit(ku, ctx, config);
});

// §428/§527 needs transactionCommitted; until the caller supplies it the document
// phase has not happened yet and is reported as null rather than guessed.
const certification = (inp.transactionCommitted === undefined)
  ? null
  : certifyDocument({
      documentId: inp.documentId,
      repositoryVersion: inp.repositoryVersion,
      unitResults,
      counts: inp.counts || {},
      transactionCommitted: inp.transactionCommitted,
    });

return [{ json: Object.assign({}, inp, {
  unitResults,
  certification,
  certificationSummary: {
    totalUnits: unitResults.length,
    certifiedUnits: unitResults.filter((r) => r.certified).length,
    reviewRequired: unitResults.filter((r) => r.reviewRequired).length,
    documentCertified: certification ? certification.certified : null,
  },
}) }];
